#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Fill training_feedback_template.hwpx with training_feedback.json.

Outputs: /root/training_feedback_ready.hwpx

Key behaviors (per task contract):
- Replace {{key}} placeholders with JSON values (supports whitespace inside braces).
- Special formatting:
  * 참석자수: digits only
  * 만족도: X.X점 (5.0점 만점)
  * 종합의견: append " 후속 심화반 검토 요망."
- For any paragraph (<hp:p>) whose text changes, remove all <hp:lineSegArray>/<hp:linesegarray>
  child elements to avoid stale layout cache in HWP viewers.
- Ensure no {{...}} remains anywhere in any XML.
- Repackage HWPX as a zip; if a root-level "mimetype" file exists, store it first uncompressed.
"""

from __future__ import annotations

import json
import os
import re
import shutil
import sys
import zipfile
import xml.etree.ElementTree as ET
from dataclasses import dataclass
from typing import Dict, List, Tuple

HWP_NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"
NS = {"hp": HWP_NS}

PLACEHOLDER_RE = re.compile(r"\{\{\s*([^{}]+?)\s*\}\}")


def _digits_only(value) -> str:
    s = str(value)
    digits = re.sub(r"\D+", "", s)
    return digits if digits else "0"


def _format_satisfaction(value) -> str:
    s = str(value)
    m = re.search(r"(\d+(?:\.\d+)?)", s)
    if not m:
        score = 0.0
    else:
        score = float(m.group(1))
    return f"{score:.1f}점 (5.0점 만점)"


def _format_overall_opinion(value) -> str:
    base = str(value).rstrip()
    return base + " 후속 심화반 검토 요망."


def build_value_map(data: Dict) -> Dict[str, str]:
    out: Dict[str, str] = {}
    for k, v in data.items():
        if k == "참석자수":
            out[k] = _digits_only(v)
        elif k == "만족도":
            out[k] = _format_satisfaction(v)
        elif k == "종합의견":
            out[k] = _format_overall_opinion(v)
        else:
            out[k] = str(v)
    return out


def localname(tag: str) -> str:
    if "}" in tag:
        return tag.split("}", 1)[1]
    return tag


def paragraph_text_nodes(p: ET.Element) -> List[ET.Element]:
    # HWPX paragraph text typically lives in hp:run/hp:t elements.
    return list(p.findall(".//hp:t", NS))


def join_paragraph_text(p: ET.Element) -> str:
    nodes = paragraph_text_nodes(p)
    return "".join((n.text or "") for n in nodes)


@dataclass
class ParagraphChange:
    para_id: str
    before: str
    after: str


def replace_placeholders(text: str, values: Dict[str, str]) -> Tuple[str, bool, List[str]]:
    """Return (new_text, changed, missing_keys).

    missing_keys includes any placeholder keys seen in text that are not in `values`.
    """

    missing: List[str] = []

    def repl(m: re.Match) -> str:
        key = m.group(1).strip()
        if key not in values:
            missing.append(key)
            return m.group(0)
        return values[key]

    new_text = PLACEHOLDER_RE.sub(repl, text)
    return new_text, (new_text != text), missing


def remove_linesegarray_children(p: ET.Element) -> int:
    removed = 0
    for child in list(p):
        if localname(child.tag).lower() == "linesegarray":
            p.remove(child)
            removed += 1
    return removed


def process_xml_file(xml_path: str, values: Dict[str, str]) -> Tuple[List[ParagraphChange], List[str]]:
    tree = ET.parse(xml_path)
    root = tree.getroot()

    changes: List[ParagraphChange] = []
    missing_keys_all: List[str] = []

    for p in root.findall(".//hp:p", NS):
        before = join_paragraph_text(p)
        if "{{" not in before:
            continue

        after, changed, missing = replace_placeholders(before, values)
        if missing:
            missing_keys_all.extend(missing)

        if not changed:
            continue

        t_nodes = paragraph_text_nodes(p)
        if not t_nodes:
            # Unexpected, but don't crash silently.
            continue

        # Put the full paragraph text into the first text node; clear the rest.
        t_nodes[0].text = after
        for n in t_nodes[1:]:
            n.text = ""

        remove_linesegarray_children(p)

        changes.append(
            ParagraphChange(
                para_id=p.get("id", ""),
                before=before,
                after=after,
            )
        )

    tree.write(xml_path, encoding="utf-8", xml_declaration=True)
    return changes, missing_keys_all


def scan_for_placeholders_in_xml(root_dir: str) -> List[str]:
    hits: List[str] = []
    for base, _, files in os.walk(root_dir):
        for fn in files:
            if not fn.lower().endswith(".xml"):
                continue
            path = os.path.join(base, fn)
            with open(path, "r", encoding="utf-8", errors="replace") as f:
                s = f.read()
            if "{{" in s or "}}" in s:
                hits.append(os.path.relpath(path, root_dir))
    return sorted(hits)


def make_hwpx_zip(src_dir: str, out_path: str) -> None:
    if os.path.exists(out_path):
        os.remove(out_path)

    mimetype_path = os.path.join(src_dir, "mimetype")

    def iter_files():
        for base, _, files in os.walk(src_dir):
            for fn in files:
                full = os.path.join(base, fn)
                rel = os.path.relpath(full, src_dir)
                yield rel, full

    all_files = sorted(iter_files(), key=lambda t: t[0])

    with zipfile.ZipFile(out_path, "w") as z:
        if os.path.isfile(mimetype_path):
            # Must be first entry, uncompressed.
            z.write(mimetype_path, arcname="mimetype", compress_type=zipfile.ZIP_STORED)

        for rel, full in all_files:
            if rel == "mimetype":
                continue
            z.write(full, arcname=rel, compress_type=zipfile.ZIP_DEFLATED)


def validate_output(
    out_hwpx: str,
    expected_values: Dict[str, str],
    modified_para_ids: Dict[str, List[str]],
) -> Tuple[bool, List[str]]:
    """Return (ok, summary_lines)."""

    lines: List[str] = []
    ok = True

    lines.append(f"exists: {os.path.exists(out_hwpx)} ({out_hwpx})")
    if not os.path.exists(out_hwpx):
        return False, lines

    is_zip = zipfile.is_zipfile(out_hwpx)
    lines.append(f"is_zipfile: {is_zip}")
    if not is_zip:
        return False, lines

    tmp = "/tmp/hwpx_validate"
    shutil.rmtree(tmp, ignore_errors=True)
    os.makedirs(tmp, exist_ok=True)

    with zipfile.ZipFile(out_hwpx) as z:
        z.extractall(tmp)

    placeholder_hits = scan_for_placeholders_in_xml(tmp)
    lines.append(f"placeholders_remaining_xml_files: {len(placeholder_hits)}")
    if placeholder_hits:
        ok = False
        lines.append("  files_with_placeholders: " + ", ".join(placeholder_hits[:20]) + (" ..." if len(placeholder_hits) > 20 else ""))

    # Validate attendee count digits only
    attendee = expected_values.get("참석자수", "")
    if not re.fullmatch(r"\d+", attendee or ""):
        ok = False
        lines.append(f"attendee_digits_only: FAIL (value={attendee!r})")
    else:
        lines.append(f"attendee_digits_only: OK ({attendee})")

    # Validate satisfaction format
    satisfaction = expected_values.get("만족도", "")
    if not re.fullmatch(r"\d+(?:\.\d)점 \(5\.0점 만점\)", satisfaction or ""):
        ok = False
        lines.append(f"satisfaction_format: FAIL (value={satisfaction!r})")
    else:
        lines.append(f"satisfaction_format: OK ({satisfaction})")

    # Validate overall opinion suffix
    overall = expected_values.get("종합의견", "")
    if not overall.endswith("후속 심화반 검토 요망."):
        ok = False
        lines.append("overall_opinion_suffix: FAIL")
    else:
        lines.append("overall_opinion_suffix: OK")

    # Validate that the fields are actually present in output (simple containment checks)
    def file_contains(rel: str, needle: str) -> bool:
        p = os.path.join(tmp, rel)
        if not os.path.exists(p):
            return False
        with open(p, "r", encoding="utf-8", errors="replace") as f:
            return needle in f.read()

    # We expect the formatted fields to show up in section0/1 text.
    if not file_contains("Contents/section0.xml", attendee):
        ok = False
        lines.append("attendee_present_in_section0: FAIL")
    else:
        lines.append("attendee_present_in_section0: OK")

    if not file_contains("Contents/section0.xml", satisfaction):
        ok = False
        lines.append("satisfaction_present_in_section0: FAIL")
    else:
        lines.append("satisfaction_present_in_section0: OK")

    if not file_contains("Contents/section1.xml", overall):
        ok = False
        lines.append("overall_present_in_section1: FAIL")
    else:
        lines.append("overall_present_in_section1: OK")

    # Validate lineSegArray removal for modified paragraphs
    for rel_xml, ids in modified_para_ids.items():
        xml_path = os.path.join(tmp, rel_xml)
        if not os.path.exists(xml_path):
            ok = False
            lines.append(f"linesegarray_check: FAIL (missing {rel_xml})")
            continue
        tree = ET.parse(xml_path)
        root = tree.getroot()
        idset = set(ids)
        for p in root.findall(".//hp:p", NS):
            pid = p.get("id", "")
            if pid not in idset:
                continue
            has_lineseg = any(localname(c.tag).lower() == "linesegarray" for c in list(p))
            if has_lineseg:
                ok = False
                lines.append(f"linesegarray_removed: FAIL ({rel_xml} p@id={pid})")

    if ok:
        lines.append("linesegarray_removed: OK")

    return ok, lines


def main() -> int:
    json_path = "/root/training_feedback.json"
    template_hwpx = "/root/training_feedback_template.hwpx"
    out_hwpx = "/root/training_feedback_ready.hwpx"

    work_dir = "/tmp/hwpx_work"

    # Load data
    with open(json_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    values = build_value_map(data)

    # Extract template
    shutil.rmtree(work_dir, ignore_errors=True)
    os.makedirs(work_dir, exist_ok=True)
    with zipfile.ZipFile(template_hwpx) as z:
        z.extractall(work_dir)

    # Process all XML files
    modified_para_ids: Dict[str, List[str]] = {}
    missing_keys_total: List[str] = []

    for base, _, files in os.walk(work_dir):
        for fn in files:
            if not fn.lower().endswith(".xml"):
                continue
            xml_path = os.path.join(base, fn)
            rel = os.path.relpath(xml_path, work_dir)
            changes, missing = process_xml_file(xml_path, values)
            if changes:
                modified_para_ids[rel] = [c.para_id for c in changes]
            if missing:
                missing_keys_total.extend(missing)

    if missing_keys_total:
        # Missing keys means placeholders could remain; treat as hard failure.
        missing_unique = sorted(set(missing_keys_total))
        print("ERROR: Missing keys in JSON for placeholders:")
        for k in missing_unique:
            print(f"  - {k}")
        return 2

    # Ensure no placeholders remain prior to repack
    remaining = scan_for_placeholders_in_xml(work_dir)
    if remaining:
        print("ERROR: Placeholders still present after replacement:")
        for rel in remaining:
            print(f"  - {rel}")
        return 3

    # Repackage
    make_hwpx_zip(work_dir, out_hwpx)

    # Validate
    ok, summary = validate_output(out_hwpx, values, modified_para_ids)
    print("\n".join(summary))

    return 0 if ok else 4


if __name__ == "__main__":
    raise SystemExit(main())

