NS = {"hp": HWP_NS}

PLACEHOLDER_RE = re.compile(r"\{\{\s*([^{}]+?)\s*\}\}")


def _digits_only(value) -> str:
    s = str(value)
    digits = re.sub(r"\D+", "", s)
    return digits if digits else "0"


def _format_satisfaction(value) -> str:
    s = str(value)
    m = re.search(r"(\d+(?:\.\d+)?)", s)
    if not m:
        score = 0.0
    else:
        score = float(m.group(1))
    return f"{score:.1f}점 (5.0점 만점)"


def _format_overall_opinion(value) -> str:
    base = str(value).rstrip()
    return base + " 후속 심화반 검토 요망."


def build_value_map(data: Dict) -> Dict[str, str]:
    out: Dict[str, str] = {}
    for k, v in data.items():
        if k == "참석자수":
            out[k] = _digits_only(v)
        elif k == "만족도":
            out[k] = _format_satisfaction(v)
        elif k == "종합의견":
            out[k] = _format_overall_opinion(v)
        else:
            out[k] = str(v)
    return out


def localname(tag: str) -> str:
    if "}" in tag:
        return tag.split("}", 1)[1]
    return tag


def paragraph_text_nodes(p: ET.Element) -> List[ET.Element]:
    # HWPX paragraph text typically lives in hp:run/hp:t elements.
    return list(p.findall(".//hp:t", NS))


def join_paragraph_text(p: ET.Element) -> str:
    nodes = paragraph_text_nodes(p)
    return "".join((n.text or "") for n in nodes)


@dataclass
class ParagraphChange:
    para_id: str
    before: str
    after: str


def replace_placeholders(text: str, values: Dict[str, str]) -> Tuple[str, bool, List[str]]:
    """Return (new_text, changed, missing_keys).

    missing_keys includes any placeholder keys seen in text that are not in `values`.
    """

    missing: List[str] = []

    def repl(m: re.Match) -> str:
        key = m.group(1).strip()
        if key not in values:
            missing.append(key)
            return m.group(0)
        return values[key]

    new_text = PLACEHOLDER_RE.sub(repl, text)
    return new_text, (new_text != text), missing


