    hits: List[str] = []
    for base, _, files in os.walk(root_dir):
        for fn in files:
            if not fn.lower().endswith(".xml"):
                continue
            path = os.path.join(base, fn)
            with open(path, "r", encoding="utf-8", errors="replace") as f:
                s = f.read()
            if "{{" in s or "}}" in s:
                hits.append(os.path.relpath(path, root_dir))
